mapper.update:
UPDATE TESTS
SET QUESTION = #{modifyExamQuestionVO.question}
	 , ANSWER_TYPE = #{modifyExamQuestionVO.answerType}
	 , ANSWER_SHEET_1 = #{modifyExamQuestionVO.answerSheet1}
	 , ANSWER_SHEET_2 = #{modifyExamQuestionVO.answerSheet2}
	 , ANSWER_SHEET_3 = #{modifyExamQuestionVO.answerSheet3}
	 , ANSWER_SHEET_4 = #{modifyExamQuestionVO.answerSheet4}
	 , ANSWER_SHEET_5 = #{modifyExamQuestionVO.answerSheet5}
	 , ANSWER_COUNT = #{modifyExamQuestionVO.answerCount}
	 , POINT_ALLOC = #{modifyExamQuestionVO.pointAlloc}
	 , MDFY_DT = SYSDATE
	 , MDFYR_ID = 'admin'
	 , CORRECT_ANSWER = #{modifyExamQuestionVO.correctAnswer}
	 , SUB_QUESTION = #{modifyExamQuestionVO.subQuestion}
WHERE ID = #{examId}
AND DEL_YN = 'N'

UPDATE TEST_SET
   SET SHOW_YN = #{showYn}
 WHERE ID = #{testSetId}

mapper.select:
SELECT COUNT(*)
  FROM TEST_ANSWERS
 WHERE TEST_SET_ID = #{testSetId}
   AND COURSE_STUDENT_ID = #{courseStudentId}

mapper.insert:

SELECT ('TN-' || TO_CHAR(SYSDATE, 'YYYYMMDD-') || LPAD(SEQ_TESTS_PK.NEXTVAL, 6, '0'))
  FROM DUAL

INSERT INTO TEST_ANSWERS
     ( ID
     , TEST_SET_ID
     , TEST_ID
     , COURSE_STUDENT_ID
     , ANSWER
     , IS_CORRECT
     , CRT_DT )
VALUES
     ( #{id}
     , #{testSetId}
     , #{testId}
     , #{courseStudentId}
     , #{answer}
     , #{isCorrect}
     , SYSDATE )
